export const api = { 
  get: async (path) => { 
    const res = await fetch(path, { method: 'GET', credentials: 'include' }); 
    if (!res.ok) throw new Error('API error'); 
    return res.json(); 
  }, 
  post: async (path, body) => { 
    const res = await fetch(path, { 
      method: 'POST', 
      headers: { 'Content-Type': 'application/json' }, 
      credentials: 'include', 
      body: JSON.stringify(body), 
    }); 
    if (!res.ok) throw new Error('API error'); 
    return res.json(); 
  } 
};

export async function fetchMachineBySerial(serial) {
  const url = `/api/machines/?serial_number_machine=${encodeURIComponent(serial)}`;

  const resp = await fetch(url, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' }, 
  });

  if (!resp.ok) {
    throw new Error('Network response was not ok');
  }
  const data = await resp.json();
  // Привести к одному объекту: если приходит массив, взять первый элемент
  if (Array.isArray(data)) {
    return data.length ? data[0] : null;
  }
  return data;
}

export async function fetchMachinesForCurrentUser() {
  const url = '/api/machines/';
  const res = await fetch(url, {
    credentials: 'include',
  });
  if (!res.ok) return [];
  const data = await res.json();
  console.log('Machines response:', data);
  return Array.isArray(data) ? data : [data];
}
